def check_if_tracker_store_async(tracker_store: TrackerStore) -> bool:
    """Evaluates if a tracker store object is async based on implementation of methods.

    :param tracker_store: tracker store object we're evaluating
    :return: if the tracker store correctly implements all async methods
    """
    return all(
        iscoroutinefunction(getattr(tracker_store, method))
        for method in _get_async_tracker_store_methods()
    )


def _get_async_tracker_store_methods() -> List[str]:
    return [
        attribute
        for attribute in dir(TrackerStore)
        if iscoroutinefunction(getattr(TrackerStore, attribute))
    ]


class TrackerDeserialisationException(RasaException):
    """Raised when an error is encountered while deserialising a tracker."""


SerializationType = TypeVar("SerializationType")


def _event_to_proto_json(
    event: Event,
    conversation_id: str,
    user_id: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    """Map an event to its ProtoJSON body, or ``None`` when it has no mapping."""
    return event_to_broker_event_dict(
        event,
        conversation_id,
        user_id,
        os.environ.get("RASA_ENVIRONMENT"),
    )


def serialise_event(
    event: Event,
    conversation_id: str,
    user_id: Optional[str] = None,
    use_proto_json: Optional[bool] = None,
) -> Dict[str, Any]:
    """Serialize an event for the tracker store.

    Pass ``use_proto_json`` from ``TrackerStore.uses_proto_json`` when
    serializing a batch. When omitted or false, the classic flat contract is
    used.

    Events without a ProtoJSON payload (CALM-only types such as ``restart``,
    and legacy twins on historical Mantle trackers) fall back to the classic
    flat format so the store keeps a complete, replayable history.
    """
    if not use_proto_json:
        return event.as_dict()
    return _event_to_proto_json(event, conversation_id, user_id) or event.as_dict()


def serialise_events(
    events: Iterable[Event],
    conversation_id: str,
    user_id: Optional[str] = None,
    use_proto_json: Optional[bool] = None,
) -> List[Dict[str, Any]]:
    """Serialize events for the tracker store, one entry per event.

    ``use_proto_json`` comes from the tracker store's engine version. When it
    is omitted, events stay in the classic flat contract.
    """
    return [
        serialise_event(event, conversation_id, user_id, use_proto_json)
        for event in events
    ]


def serialise_events_for_broker(
    events: Iterable[Event],
    conversation_id: str,
    user_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Serialize events for the ProtoJSON broker contract.

    Unlike :func:`serialise_events`, events without a ProtoJSON payload are
    omitted: the broker publishes the versioned contract only, and the proto has
    no representation for CALM-only or legacy twin types.
    """
    bodies = []
    for event in events:
        body = _event_to_proto_json(event, conversation_id, user_id)
        if body is not None:
            bodies.append(body)
    return bodies


class SerializedTrackerRepresentation(Generic[SerializationType]):
    """Mixin class for specifying different serialization methods per tracker store."""

    @staticmethod
    def serialise_tracker(
        tracker: DialogueStateTracker,
        use_proto_json: Optional[bool] = None,
    ) -> SerializationType:
        """Requires implementation to return representation of tracker."""
        raise NotImplementedError()


class SerializedTrackerAsText(SerializedTrackerRepresentation[Text]):
    """Mixin class that returns the serialized tracker as string."""

    @staticmethod
    def serialise_tracker(
        tracker: DialogueStateTracker,
        use_proto_json: Optional[bool] = None,
    ) -> Text:
        """Serializes the tracker, returns representation of the tracker."""
        dialogue = tracker.as_dialogue()
        dialogue_dict = dialogue.as_dict()
        dialogue_dict["events"] = serialise_events(
            tracker.events,
            tracker.sender_id,
            tracker.user_id,
            use_proto_json=use_proto_json,
        )
        dialogue_dict["sender_id"] = tracker.sender_id

        return json.dumps(dialogue_dict)


class SerializedTrackerAsDict(SerializedTrackerRepresentation[Dict]):
    """Mixin class that returns the serialized tracker as dictionary."""

    @staticmethod
    def serialise_tracker(
        tracker: DialogueStateTracker,
        use_proto_json: Optional[bool] = None,
    ) -> Dict:
        """Serializes the tracker, returns representation of the tracker."""
        serialized_tracker = tracker.as_dialogue().as_dict()
        serialized_tracker["events"] = serialise_events(
            tracker.events,
            tracker.sender_id,
            tracker.user_id,
            use_proto_json=use_proto_json,
        )
        serialized_tracker.update({"sender_id": tracker.sender_id})

        serialized_user_id = serialized_tracker.get(USER_ID)
        if serialized_user_id is None:
            # Remove user_id key if it's None to avoid storing null values
            serialized_tracker.pop(USER_ID)

        serialized_conversation_started_timestamp = serialized_tracker.get(
            "conversation_started_timestamp"
        )
        if serialized_conversation_started_timestamp is None:
            # Remove conversation_started_timestamp key if it's None
            # to avoid storing null values
            serialized_tracker.pop("conversation_started_timestamp")

        return serialized_tracker


class TrackerStore:
    """Represents common behavior and interface for all `TrackerStore`s."""

    use_permissive_slots: bool = False
    """When set, trackers are initialised with a permissive ``AnySlotDict`` (slots
    created on demand) instead of the domain's fixed slot set.

    Used by engines whose conversational state schema lives outside the domain
    (e.g. Mantle, which owns slot names via its memory layer). Defaults to
    ``False`` so every existing tracker store keeps its strict, domain-gated
    behaviour. Set after construction, like :attr:`domain`."""

    def __init__(
        self,
        domain: Optional[Domain],
        event_broker: Optional[EventBroker] = None,
        **kwargs: Dict[Text, Any],
    ) -> None:
        """Create a TrackerStore.

        Args:
            domain: The `Domain` to initialize the `DialogueStateTracker`.
            event_broker: An event broker to publish any new events to another
                destination.
            kwargs: Additional kwargs.
        """
        self._domain = domain or Domain.empty()
        self.event_broker = event_broker
        self._engine_version: Optional[str] = None
        self.max_event_history: Optional[int] = None

    @property
    def engine_version(self) -> Optional[str]:
        """Return the engine version used by this tracker store."""
        return self._engine_version

    @engine_version.setter
    def engine_version(self, engine_version: Optional[str]) -> None:
        """Set the engine version on this store and its event broker."""
        self._engine_version = engine_version
        if self.event_broker is not None and engine_version is not None:
            self.event_broker.engine_version = engine_version

    def uses_proto_json(self) -> bool:
        """Return whether this store writes and streams Mantle ProtoJSON.

        The loaded model's engine version is the only signal. Project layout
        and the shape of stored events are not consulted. Retrieve still
        dual-reads both contracts so an older conversation loads either way.
        """
        return self.engine_version == MANTLE_ENGINE_VERSION

    @staticmethod
    def create(
        obj: Union[TrackerStore, EndpointConfig, None],
        domain: Optional[Domain] = None,
        event_broker: Optional[EventBroker] = None,
    ) -> TrackerStore:
        """Factory to create a tracker store."""
        if isinstance(obj, TrackerStore):
            return obj

        import pymongo.errors
        import sqlalchemy.exc
        from botocore.exceptions import BotoCoreError, ClientError

        try:
            _tracker_store = plugin_manager().hook.create_tracker_store(
                endpoint_config=obj,
                domain=domain,
                event_broker=event_broker,
            )

            tracker_store = (
                _tracker_store
                if _tracker_store
                else create_tracker_store(obj, domain, event_broker)
            )

            return tracker_store
        except (
            BotoCoreError,
            ClientError,
            pymongo.errors.ConnectionFailure,
            sqlalchemy.exc.OperationalError,
            ConnectionError,
            pymongo.errors.OperationFailure,
        ) as error:
            raise ConnectionException(
                "Cannot connect to tracker store." + str(error)
            ) from error

    async def get_or_create_tracker(
        self,
        sender_id: Text,
        max_event_history: Optional[int] = None,
        append_action_listen: bool = True,
        user_id: Optional[Text] = None,
    ) -> "DialogueStateTracker":
        """Returns tracker or creates one if the retrieval returns None.

        Args:
            sender_id: Conversation ID associated with the requested tracker.
            max_event_history: Value to update the tracker store's max event history to.
            append_action_listen: Whether or not to append an initial `action_listen`.
            user_id: Optional user ID associated with the tracker.
        """
        self.max_event_history = max_event_history

        tracker = await self.retrieve(sender_id)

        if tracker is None:
            tracker = await self.create_tracker(
                sender_id, append_action_listen=append_action_listen, user_id=user_id
            )

        return tracker

    def init_tracker(
        self, sender_id: Text, user_id: Optional[Text] = None
    ) -> "DialogueStateTracker":
        """Returns a Dialogue State Tracker."""
        return DialogueStateTracker(
            sender_id,
            self._tracker_slots(),
            max_event_history=self.max_event_history,
            user_id=user_id,
        )

    async def create_tracker(
        self,
        sender_id: Text,
        append_action_listen: bool = True,
        user_id: Optional[Text] = None,
    ) -> DialogueStateTracker:
        """Creates a new tracker for `sender_id`.

        The tracker begins with a `SessionStarted` event and is initially listening.

        Args:
            sender_id: Conversation ID associated with the tracker.
            append_action_listen: Whether or not to append an initial `action_listen`.
            user_id: Optional user ID associated with the tracker.

        Returns:
            The newly created tracker for `sender_id`.
        """
        tracker = self.init_tracker(sender_id, user_id=user_id)

        if append_action_listen:
            tracker.update(ActionExecuted(ACTION_LISTEN_NAME))

        await self.save(tracker)

        return tracker

    async def save(self, tracker: DialogueStateTracker) -> None:
        """Save method that will be overridden by specific tracker."""
        raise NotImplementedError()

    async def exists(self, conversation_id: Text) -> bool:
        """Checks if tracker exists for the specified ID.

        This method may be overridden by the specific tracker store for
        faster implementations.

        Args:
            conversation_id: Conversation ID to check if the tracker exists.

        Returns:
            `True` if the tracker exists, `False` otherwise.
        """
        return await self.retrieve(conversation_id) is not None

    async def retrieve(self, sender_id: Text) -> Optional[DialogueStateTracker]:
        """Retrieves tracker for the latest conversation session.

        This method will be overridden by the specific tracker store.

        Args:
            sender_id: Conversation ID to fetch the tracker for.

        Returns:
            Tracker containing events from the latest conversation sessions.
        """
        raise NotImplementedError()

    async def delete(self, sender_id: str) -> None:
        """Delete tracker for the given sender_id.

        Args:
            sender_id: Conversation ID to delete the tracker for.
        """
        raise NotImplementedError()

    async def update(
        self, tracker: DialogueStateTracker, apply_deletion_only: bool = True
    ) -> None:
        """Replace an existing tracker with a new one.

        Args:
            tracker: The tracker to update.
            apply_deletion_only: If True (default), only a trim/delete step is applied
                (SQL: timestamp-based delete). If False, content-only updates may be
                applied when no rows are deleted (e.g. anonymization). Other stores
                ignore this; SQL uses it to avoid conflating deletion with content-only.
        """
        raise NotImplementedError()

    def _get_conversation_started_timestamp(
        self, tracker: DialogueStateTracker
    ) -> Optional[float]:
        """Extract the timestamp of the first event in the conversation.

        This timestamp represents when the conversation started and can be stored
        as a separate field in tracker stores for efficient sorting and querying.

        Args:
            tracker: Tracker to extract timestamp from.

        Returns:
            Timestamp of the first event, or None if no events exist.
        """
        if tracker.conversation_started_timestamp is not None:
            return tracker.conversation_started_timestamp
        if tracker.events:
            return tracker.events[0].timestamp
        return None

    async def retrieve_full_tracker(
        self, conversation_id: Text
    ) -> Optional[DialogueStateTracker]:
        """Retrieve method for fetching all tracker events.

        Fetches events across conversation sessions. The default implementation
        uses `self.retrieve()`.

        Args:
            conversation_id: The conversation ID to retrieve the tracker for.

        Returns:
            The fetch tracker containing all events across session starts.
        """
        return await self.retrieve(conversation_id)

    async def get_or_create_full_tracker(
        self,
        sender_id: Text,
        append_action_listen: bool = True,
    ) -> "DialogueStateTracker":
        """Returns tracker or creates one if the retrieval returns None.

        Args:
            sender_id: Conversation ID associated with the requested tracker.
            append_action_listen: Whether to append an initial `action_listen`.

        Returns:
            The tracker for the conversation ID.
        """
        tracker = await self.retrieve_full_tracker(sender_id)

        if tracker is None:
            tracker = await self.create_tracker(
                sender_id, append_action_listen=append_action_listen
            )

        return tracker

    async def events_not_yet_persisted(
        self, tracker: DialogueStateTracker
    ) -> List[Event]:
        """Returns events on `tracker` that are not yet in the store.

        Compares `tracker` to the latest-session tracker from
        :meth:`retrieve` via :meth:`TrackerEventDiffEngine.event_difference`.
        Callers that both stream and persist (e.g. DynamoDB `save`) can
        compute this list once and pass it to :meth:`stream_events` as
        `new_events` to avoid a second retrieve.

        Args:
            tracker: In-memory tracker that may contain events beyond what is
                stored for `tracker.sender_id`.

        Returns:
            Events present on `tracker` after the stored latest-session
            offset. Empty when nothing new needs persisting.
        """
        stored = await self.retrieve(tracker.sender_id)
        return TrackerEventDiffEngine.event_difference(stored, tracker)

    async def stream_events(
        self,
        tracker: DialogueStateTracker,
        new_events: Optional[List[Event]] = None,
    ) -> None:
        """Streams new tracker events to a message broker.

        When ``new_events`` is omitted, loads the stored tracker and diffs it
        against ``tracker``. Pass a precomputed list (e.g. from
        :meth:`events_not_yet_persisted`) to skip that retrieve when the
        caller already has the events to publish.

        Args:
            tracker: Tracker whose new events should be published.
            new_events: Optional precomputed unsaved events. When provided,
                :meth:`retrieve` is not called.
        """
        if self.event_broker is None:
            structlogger.debug(
                "tracker_store.stream_events.no_broker_configured",
                event_info="No event broker configured. Skipping streaming events.",
            )
            return None

        if (
            hasattr(self.event_broker, "stream_pii")
            and not self.event_broker.stream_pii
        ):
            # If the event broker is configured to not stream un-anonymized events,
            # skip streaming
            structlogger.debug(
                "tracker_store.stream_events.no_streaming",
                event_info="Un-anonymized events will not be published "
                "to the event broker.",
            )
            return None

        if new_events is None:
            new_events = await self.events_not_yet_persisted(tracker)

        await self._stream_new_events(
            self.event_broker, new_events, tracker.sender_id, tracker.user_id
        )

    async def _stream_new_events(
        self,
        event_broker: EventBroker,
        new_events: List[Event],
        sender_id: str,
        user_id: Optional[str] = None,
    ) -> None:
        """Publishes new tracker events to a message broker."""
        if self.uses_proto_json():
            for body in serialise_events_for_broker(new_events, sender_id, user_id):
                event_broker.publish(body)
            return

        for event in new_events:
            body = event.as_dict()
            body["metadata"] = {
                **body.get("metadata", {}),
                "rasa_environment": os.environ.get("RASA_ENVIRONMENT"),
            }
            body = {"sender_id": sender_id, "user_id": user_id, **body}
            event_broker.publish(body)

    async def keys(self) -> Iterable[Text]:
        """Returns the set of values for the tracker store's primary key."""
        raise NotImplementedError()

    async def get_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Retrieves serialized trackers for a given user_id.

        Delegates to :meth:`get_serialized_trackers_by_user_id`, which each
        subclass must implement. Subclasses do not need to override this method.

        Args:
            user_id: User ID to fetch trackers for.
            limit: Optional maximum number of trackers to return. If None, returns all
                matching trackers. Useful for pagination.
            skip: Optional number of trackers to skip before returning results. If None,
                starts from the beginning. Useful for pagination.

        Returns:
            List of serialized tracker dicts associated with the user_id.
        """
        return await self.get_serialized_trackers_by_user_id(
            user_id, limit=limit, skip=skip
        )

    async def get_serialized_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Retrieves serialized trackers for a given user_id without event replay.

        Returns tracker data directly from the store in events-centric format,
        skipping ``DialogueStateTracker.from_dict()`` and ``current_state()``
        reconstruction. This is significantly faster than
        :meth:`get_trackers_by_user_id` because no event replay is performed.

        Each returned dict has the shape::

            {
                "sender_id": str,
                "events": List[Dict],
                "user_id": Optional[str],
                "conversation_started_timestamp": Optional[float],
                "current_session_id": Optional[str],
            }

        Args:
            user_id: User ID to fetch trackers for.
            limit: Optional maximum number of trackers to return.
            skip: Optional number of trackers to skip before returning results.

        Returns:
            List of serialized tracker dicts associated with the user_id.
        """
        raise NotImplementedError()

    def _sort_key_serialized(self, tracker_dict: Dict[str, Any]) -> Tuple[float, str]:
        """Sorting key for serialized tracker dicts.

        Mirrors :meth:`_sort_key` but operates on raw dicts instead of tracker
        objects, avoiding event replay.

        Args:
            tracker_dict: Serialized tracker dict with ``sender_id``,
                ``conversation_started_timestamp``, and ``events`` keys.

        Returns:
            Tuple of (timestamp, sender_id) for consistent ordering.
        """
        sender_id = tracker_dict.get("sender_id", "")
        timestamp = tracker_dict.get("conversation_started_timestamp")
        if timestamp is not None:
            return float(timestamp), sender_id
        events = tracker_dict.get("events") or []
        if events:
            return float(events[0].get("timestamp", 0.0)), sender_id
        return 0.0, sender_id

    def _apply_pagination_serialized(
        self,
        trackers: List[Dict[str, Any]],
        skip: Optional[int],
        limit: Optional[int],
    ) -> List[Dict[str, Any]]:
        """Apply skip/limit pagination to a list of serialized tracker dicts.

        Args:
            trackers: List of serialized tracker dicts to paginate.
            skip: Optional number of items to skip.
            limit: Optional maximum number of items to return.

        Returns:
            Paginated list of serialized tracker dicts.
        """
        if skip is not None and skip > 0:
            trackers = trackers[skip:]
        if limit is not None and limit > 0:
            trackers = trackers[:limit]
        return trackers

    @staticmethod
    def _current_session_id_from_events(
        events: List[Dict[str, Any]],
    ) -> Optional[str]:
        """Derive ``current_session_id`` from a serialized event list without replay.

        Classic events store the session ID in ``metadata["session_id"]``. Mantle
        ProtoJSON lifts it to a top-level ``session_id`` envelope field. When the
        last event is a ``ConversationInactive`` (flat ``"event": "inactive"`` or
        ProtoJSON ``inactive`` payload), the session has ended and ``None`` is
        returned.

        Args:
            events: List of serialized event dicts (classic flat JSON or Mantle
                ProtoJSON).

        Returns:
            The active session ID string, or ``None`` if the conversation is
            inactive or no events carry a session ID.
        """
        if not events:
            return None
        last_event = events[-1]
        is_flat_inactive = last_event.get(EVENT_KEY) == ConversationInactive.type_name
        is_proto_inactive = EVENT_KEY not in last_event and "inactive" in last_event
        if is_flat_inactive or is_proto_inactive:
            return None

        proto_session_id = last_event.get(METADATA_SESSION_ID)
        if isinstance(proto_session_id, str) and proto_session_id.strip():
            return proto_session_id

        metadata = last_event.get(METADATA_KEY) or {}
        if isinstance(metadata, str):
            try:
                metadata = json.loads(metadata)
            except (TypeError, JSONDecodeError):
                return None
        if not isinstance(metadata, dict):
            return None
        return metadata.get(METADATA_SESSION_ID)

    async def count_conversations(self, after_timestamp: float = 0.0) -> int:
        """Returns the number of conversations that have occurred after a timestamp.

        By default, this method returns the number of conversations that
        have occurred after the Unix epoch (i.e. timestamp 0). A conversation
        is considered to have occurred after a timestamp if at least one event
        happened after that timestamp.
        """
        tracker_keys = await self.keys()

        conversation_count = 0
        for key in tracker_keys:
            tracker = await self.retrieve(key)
            if tracker is None or not tracker.events:
                continue

            last_event = tracker.events[-1]
            if last_event.timestamp >= after_timestamp:
                conversation_count += 1

        return conversation_count

    def deserialise_tracker(
        self, sender_id: Text, serialised_tracker: Union[Text, bytes]
    ) -> Optional[DialogueStateTracker]:
        """Deserializes the tracker and returns it."""
        try:
            dialogue = Dialogue.from_parameters(json.loads(serialised_tracker))
        except (UnicodeDecodeError, JSONDecodeError) as e:
            raise TrackerDeserialisationException(
                "Tracker cannot be deserialised. "
                "Trackers must be serialised as json. "
                "Support for deserialising pickled trackers has been removed."
            ) from e

        # Create tracker with user_id from dialogue
        tracker = self.init_tracker(sender_id, user_id=dialogue.user_id)

        tracker.recreate_from_dialogue(dialogue)

        return tracker

    @property
    def domain(self) -> Domain:
        """Returns the domain of the tracker store."""
        return self._domain

    @domain.setter
    def domain(self, domain: Optional[Domain]) -> None:
        self._domain = domain or Domain.empty()

    def _tracker_slots(self) -> Optional[List["Slot"]]:
        """Slots used to initialise a tracker.

        Returns ``None`` when :attr:`use_permissive_slots` is set so the tracker
        builds an ``AnySlotDict`` that accepts any slot on demand; otherwise the
        domain's fixed slot list. Centralises the choice so every backend's
        reconstruction path stays consistent.
        """
        if self.use_permissive_slots:
            return None
        return self.domain.slots


class InMemoryTrackerStore(TrackerStore, SerializedTrackerAsText):
    """Stores conversation history in memory."""

    def __init__(
        self,
        domain: Domain,
        event_broker: Optional[EventBroker] = None,
        **kwargs: Dict[Text, Any],
    ) -> None:
        """Initializes the tracker store."""
        self.store: Dict[Text, Text] = {}
        super().__init__(domain, event_broker, **kwargs)

    async def save(self, tracker: DialogueStateTracker) -> None:
        """Updates and saves the current conversation state."""
        await self.stream_events(tracker)
        # Ensure conversation_started_timestamp is set (for backward compatibility)
        tracker.ensure_conversation_started_timestamp()
        serialised = self.serialise_tracker(
            tracker, use_proto_json=self.uses_proto_json()
        )
        self.store[tracker.sender_id] = serialised

    async def delete(self, sender_id: Text) -> None:
        """Delete tracker for the given sender_id."""
        if sender_id not in self.store:
            structlogger.info(
                "in_memory_tracker_store.delete.no_tracker_for_sender_id",
                event_info=f"Could not find tracker for conversation ID '{sender_id}'.",
            )
            return None

        del self.store[sender_id]

        structlogger.info(
            "in_memory_tracker_store.delete.deleted_tracker",
            sender_id=sender_id,
        )

    async def retrieve(self, sender_id: Text) -> Optional[DialogueStateTracker]:
        """Returns tracker matching sender_id."""
        return await self._retrieve(sender_id, fetch_all_sessions=False)

    async def keys(self) -> Iterable[Text]:
        """Returns sender_ids of the Tracker Store in memory."""
        return self.store.keys()

    async def retrieve_full_tracker(
        self, sender_id: Text
    ) -> Optional[DialogueStateTracker]:
        """Returns tracker matching sender_id.

        Args:
            sender_id: Conversation ID to fetch the tracker for.
        """
        return await self._retrieve(sender_id, fetch_all_sessions=True)

    async def _retrieve(
        self, sender_id: Text, fetch_all_sessions: bool
    ) -> Optional[DialogueStateTracker]:
        """Returns tracker matching sender_id.

        Args:
            sender_id: Conversation ID to fetch the tracker for.
            fetch_all_sessions: Whether to fetch all sessions or only the last one.
        """
        if sender_id not in self.store:
            structlogger.debug(
                "in_memory_tracker_store.retrieve.no_tracker_for_sender_id",
                event_info=f"Could not find tracker for conversation ID '{sender_id}'.",
            )
            return None

        tracker = self.deserialise_tracker(sender_id, self.store[sender_id])

        if not tracker:
            structlogger.debug(
                "in_memory_tracker_store.retrieve.failed_to_deserialize_tracker",
                event_info=(
                    f"Could not deserialize tracker "
                    f"for conversation ID '{sender_id}'.",
                ),
            )
            return None

        if fetch_all_sessions:
            return tracker

        return rasa.shared.core.trackers.get_latest_replay_safe_session_tracker(
            tracker,
            start_session_after_expiry=(
                self.domain.session_config.start_session_after_expiry
            ),
        )

    async def update(
        self, tracker: DialogueStateTracker, apply_deletion_only: bool = True
    ) -> None:
        """Replace an existing tracker with a new one.

        A replace is a maintenance write — the privacy manager's anonymization
        and deletion jobs are its only callers — so it must not publish on the
        event broker. Only ``save`` streams, which matches how every other
        store implements ``update``.

        Args:
            tracker: The tracker to update.
            apply_deletion_only: Ignored for in-memory store (full overwrite).
        """
        # Ensure conversation_started_timestamp is set (for backward compatibility)
        tracker.ensure_conversation_started_timestamp()
        self.store[tracker.sender_id] = self.serialise_tracker(
            tracker, use_proto_json=self.uses_proto_json()
        )

    async def get_serialized_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Returns serialized tracker dicts for a given user_id without event replay.

        Iterates the in-memory store, parses each JSON blob, filters by ``user_id``,
        then sorts and paginates using the base-class helpers.

        Args:
            user_id: User ID to fetch trackers for.
            limit: Maximum number of trackers to return. ``None`` returns all.
            skip: Number of trackers to skip. ``None`` starts from the beginning.

        Returns:
            List of dicts, each containing ``sender_id``, ``events``,
            ``user_id``, ``conversation_started_timestamp``, and
            ``current_session_id``.
        """
        result = []
        for sender_id, raw in self.store.items():
            try:
                blob = json.loads(raw)
            except (JSONDecodeError, TypeError):
                continue
            if blob.get(USER_ID) != user_id:
                continue
            events = blob.get("events") or []
            raw_ts = blob.get("conversation_started_timestamp")
            result.append(
                {
                    "sender_id": sender_id,
                    "events": events,
                    USER_ID: user_id,
                    "conversation_started_timestamp": float(raw_ts)
                    if raw_ts is not None
                    else None,
                    "current_session_id": self._current_session_id_from_events(events),
                }
            )
        result.sort(key=self._sort_key_serialized)
        return self._apply_pagination_serialized(result, skip, limit)


def validate_port(port: Any) -> Optional[int]:
    """Ensure that port can be converted to integer.

    Raises:
        RasaException if port cannot be cast to integer.
    """
    if port is not None and not isinstance(port, int):
        try:
            port = int(port)
        except ValueError as e:
            raise RasaException(f"The port '{port}' cannot be cast to integer.") from e

    return port


class FailSafeTrackerStore(TrackerStore):
    """Tracker store wrapper.

    Allows a fallback to a different tracker store in case of errors.
    """

    def __init__(
        self,
        tracker_store: TrackerStore,
        on_tracker_store_error: Optional[Callable[[Exception], None]] = None,
        fallback_tracker_store: Optional[TrackerStore] = None,
    ) -> None:
        """Create a `FailSafeTrackerStore`.

        Args:
            tracker_store: Primary tracker store.
            on_tracker_store_error: Callback which is called when there is an error
                in the primary tracker store.
            fallback_tracker_store: Fallback tracker store.
        """
        self._fallback_tracker_store: Optional[TrackerStore] = fallback_tracker_store
        self._tracker_store = tracker_store
        self._on_tracker_store_error = on_tracker_store_error

        super().__init__(tracker_store.domain, tracker_store.event_broker)

    @property
    def domain(self) -> Domain:
        """Returns the domain of the primary tracker store."""
        return self._tracker_store.domain

    @domain.setter
    def domain(self, domain: Optional[Domain]) -> None:
        self._tracker_store.domain = domain

        if self._fallback_tracker_store:
            self._fallback_tracker_store.domain = domain

    @property
    def use_permissive_slots(self) -> bool:
        """Returns the permissive-slots setting of the primary tracker store."""
        return self._tracker_store.use_permissive_slots

    @use_permissive_slots.setter
    def use_permissive_slots(self, use_permissive_slots: bool) -> None:
        self._tracker_store.use_permissive_slots = use_permissive_slots

        if self._fallback_tracker_store:
            self._fallback_tracker_store.use_permissive_slots = use_permissive_slots

    @property
    def engine_version(self) -> Optional[str]:
        """Return the engine version of the primary tracker store."""
        return self._tracker_store.engine_version

    @engine_version.setter
    def engine_version(self, engine_version: Optional[str]) -> None:
        """Set the engine version on primary and fallback tracker stores."""
        self._tracker_store.engine_version = engine_version
        if self._fallback_tracker_store:
            self._fallback_tracker_store.engine_version = engine_version

    @property
    def fallback_tracker_store(self) -> TrackerStore:
        """Returns the fallback tracker store."""
        if not self._fallback_tracker_store:
            fallback = InMemoryTrackerStore(
                self._tracker_store.domain, self._tracker_store.event_broker
            )
            # Mirror the primary store's slot behaviour so the fallback persists
            # the same slots (e.g. permissive AnySlotDict for Mantle).
            fallback.use_permissive_slots = self._tracker_store.use_permissive_slots
            fallback.engine_version = self._tracker_store.engine_version
            self._fallback_tracker_store = fallback

        return self._fallback_tracker_store

    def on_tracker_store_error(self, error: Exception) -> None:
        """Calls the callback when there is an error in the primary tracker store."""
        if self._on_tracker_store_error:
            self._on_tracker_store_error(error)
        else:
            structlogger.error(
                "fail_safe_tracker_store.tracker_store_error",
                event_info=(
                    f"Error happened when trying to save conversation tracker to "
                    f"'{self._tracker_store.__class__.__name__}'. Falling back to use "
                    f"the '{InMemoryTrackerStore.__name__}'. Please "
                    f"investigate the following error: {error}."
                ),
                exc_info=error,
            )

    async def retrieve(self, sender_id: Text) -> Optional[DialogueStateTracker]:
        """Calls `retrieve` method of primary tracker store."""
        try:
            return await self._tracker_store.retrieve(sender_id)
        except Exception as e:
            self.on_tracker_store_retrieve_error(e)
            return None

    async def keys(self) -> Iterable[Text]:
        """Calls `keys` method of primary tracker store."""
        try:
            return await self._tracker_store.keys()
        except Exception as e:
            self.on_tracker_store_error(e)
            return []

    async def save(self, tracker: DialogueStateTracker) -> None:
        """Calls `save` method of primary tracker store."""
        try:
            await self._tracker_store.save(tracker)
        except Exception as e:
            self.on_tracker_store_error(e)
            await self.fallback_tracker_store.save(tracker)

    async def delete(self, sender_id: Text) -> None:
        """Delete tracker for the given sender_id."""
        try:
            await self._tracker_store.delete(sender_id)
        except Exception as e:
            self.on_tracker_store_error(e)
            await self.fallback_tracker_store.delete(sender_id)

    async def update(
        self, tracker: DialogueStateTracker, apply_deletion_only: bool = True
    ) -> None:
        """Replace an existing tracker with a new one."""
        try:
            await self._tracker_store.update(
                tracker, apply_deletion_only=apply_deletion_only
            )
        except Exception as e:
            self.on_tracker_store_error(e)
            await self.fallback_tracker_store.update(
                tracker, apply_deletion_only=apply_deletion_only
            )

    async def retrieve_full_tracker(
        self, sender_id: Text
    ) -> Optional[DialogueStateTracker]:
        """Calls `retrieve_full_tracker` method of primary tracker store.

        Args:
            sender_id: The sender id of the tracker to retrieve.
        """
        try:
            return await self._tracker_store.retrieve_full_tracker(sender_id)
        except Exception as e:
            self.on_tracker_store_retrieve_error(e)
            return None

    def on_tracker_store_retrieve_error(self, error: Exception) -> None:
        """Calls `_on_tracker_store_error` callable attribute if set.

        Otherwise, logs the error.

        Args:
            error: The error that occurred.
        """
        if self._on_tracker_store_error:
            self._on_tracker_store_error(error)
        else:
            structlogger.error(
                "fail_safe_tracker_store.tracker_store_retrieve_error",
                event_info=(
                    f"Error happened when trying to retrieve conversation tracker from "
                    f"'{self._tracker_store.__class__.__name__}'. Falling back to use "
                    f"the '{InMemoryTrackerStore.__name__}'."
                ),
                exc_info=error,
            )

    async def get_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Calls `get_trackers_by_user_id` method of primary tracker store."""
        try:
            return await self._tracker_store.get_trackers_by_user_id(
                user_id, limit=limit, skip=skip
            )
        except Exception as e:
            self.on_tracker_store_error(e)
            return await self.fallback_tracker_store.get_trackers_by_user_id(
                user_id, limit=limit, skip=skip
            )

    async def get_serialized_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Delegates to primary tracker store; falls back on error.

        Args:
            user_id: User ID to fetch trackers for.
            limit: Optional maximum number of trackers to return.
            skip: Optional number of trackers to skip.

        Returns:
            List of serialized tracker dicts.
        """
        try:
            return await self._tracker_store.get_serialized_trackers_by_user_id(
                user_id, limit=limit, skip=skip
            )
        except Exception as e:
            self.on_tracker_store_error(e)
            return await self.fallback_tracker_store.get_serialized_trackers_by_user_id(
                user_id, limit=limit, skip=skip
            )


def _create_from_endpoint_config(
    endpoint_config: Optional[EndpointConfig] = None,
    domain: Optional[Domain] = None,
    event_broker: Optional[EventBroker] = None,
) -> TrackerStore:
    """Given an endpoint configuration, create a proper tracker store object."""
    from rasa.core.tracker_stores.dynamo_tracker_store import DynamoTrackerStore
    from rasa.core.tracker_stores.mongo_tracker_store import MongoTrackerStore
    from rasa.core.tracker_stores.redis_tracker_store import (
        RedisTrackerStore,
    )
    from rasa.core.tracker_stores.sql_tracker_store import SQLTrackerStore

    domain = domain or Domain.empty()

    if endpoint_config is None or endpoint_config.type is None:
        # default tracker store if no type is set
        tracker_store: TrackerStore = InMemoryTrackerStore(domain, event_broker)
    elif endpoint_config.type.lower() == "redis":
        tracker_store = RedisTrackerStore(
            domain=domain,
            host=endpoint_config.url,
            event_broker=event_broker,
            **endpoint_config.kwargs,
        )
    elif endpoint_config.type.lower() == "mongod":
        tracker_store = MongoTrackerStore(
            domain=domain,
            host=endpoint_config.url,
            event_broker=event_broker,
            **endpoint_config.kwargs,
        )
    elif endpoint_config.type.lower() == "sql":
        tracker_store = SQLTrackerStore(
            domain=domain,
            host=endpoint_config.url,
            event_broker=event_broker,
            **endpoint_config.kwargs,
        )
    elif endpoint_config.type.lower() == "dynamo":
        tracker_store = DynamoTrackerStore(
            domain=domain, event_broker=event_broker, **endpoint_config.kwargs
        )
    else:
        tracker_store = _load_from_module_name_in_endpoint_config(
            domain, endpoint_config, event_broker
        )

    structlogger.debug(
        "tracker_store.create_tracker_store_from_endpoint_config",
        event_info=f"Connected to {tracker_store.__class__.__name__}.",
    )

    return tracker_store


def _load_from_module_name_in_endpoint_config(
    domain: Domain, store: EndpointConfig, event_broker: Optional[EventBroker] = None
) -> TrackerStore:
    """Initializes a custom tracker.

    Defaults to the InMemoryTrackerStore if the module path can not be found.

    Args:
        domain: defines the universe in which the assistant operates
        store: the specific tracker store
        event_broker: an event broker to publish events

    Returns:
        a tracker store from a specified type in a stores endpoint configuration
    """
    try:
        tracker_store_class = rasa.shared.utils.common.class_from_module_path(
            store.type
        )

        return tracker_store_class(
            host=store.url, domain=domain, event_broker=event_broker, **store.kwargs
        )
    except (AttributeError, ImportError):
        rasa.shared.utils.io.raise_warning(
            f"Tracker store with type '{store.type}' not found. "
            f"Using `InMemoryTrackerStore` instead."
        )
        return InMemoryTrackerStore(domain)


def create_tracker_store(
    endpoint_config: Optional[EndpointConfig],
    domain: Optional[Domain] = None,
    event_broker: Optional[EventBroker] = None,
) -> TrackerStore:
    """Creates a tracker store based on the current configuration."""
    tracker_store = _create_from_endpoint_config(endpoint_config, domain, event_broker)

    if not check_if_tracker_store_async(tracker_store):
        rasa.shared.utils.io.raise_deprecation_warning(
            f"Tracker store implementation "
            f"{tracker_store.__class__.__name__} "
            f"is not asynchronous. Non-asynchronous tracker stores "
            f"are currently deprecated and will be removed in 4.0. "
            f"Please make the following methods async: "
            f"{_get_async_tracker_store_methods()}"
        )
        tracker_store = AwaitableTrackerStore(tracker_store)

    return tracker_store


class AwaitableTrackerStore(TrackerStore):
    """Wraps a tracker store so it can be implemented with async overrides."""

    def __init__(
        self,
        tracker_store: TrackerStore,
    ) -> None:
        """Create a `AwaitableTrackerStore`.

        Args:
            tracker_store: the wrapped tracker store.
        """
        self._tracker_store = tracker_store

        super().__init__(tracker_store.domain, tracker_store.event_broker)

    @property
    def domain(self) -> Domain:
        """Returns the domain of the primary tracker store."""
        return self._tracker_store.domain

    @domain.setter
    def domain(self, domain: Optional[Domain]) -> None:
        """Setter method to modify the wrapped tracker store's domain field."""
        self._tracker_store.domain = domain or Domain.empty()

    @property
    def use_permissive_slots(self) -> bool:
        """Returns the permissive-slots setting of the wrapped tracker store."""
        return self._tracker_store.use_permissive_slots

    @use_permissive_slots.setter
    def use_permissive_slots(self, use_permissive_slots: bool) -> None:
        """Setter to modify the wrapped tracker store's permissive-slots field."""
        self._tracker_store.use_permissive_slots = use_permissive_slots

    @property
    def engine_version(self) -> Optional[str]:
        """Return the engine version of the wrapped tracker store."""
        return self._tracker_store.engine_version

    @engine_version.setter
    def engine_version(self, engine_version: Optional[str]) -> None:
        """Set the engine version on the wrapped tracker store."""
        self._tracker_store.engine_version = engine_version

    @staticmethod
    def create(
        obj: Union[TrackerStore, EndpointConfig, None],
        domain: Optional[Domain] = None,
        event_broker: Optional[EventBroker] = None,
    ) -> TrackerStore:
        """Wrapper to call `create` method of primary tracker store."""
        if isinstance(obj, TrackerStore):
            return AwaitableTrackerStore(obj)
        elif isinstance(obj, EndpointConfig):
            return AwaitableTrackerStore(_create_from_endpoint_config(obj))
        else:
            raise ValueError(
                f"{type(obj).__name__} supplied "
                f"but expected object of type {TrackerStore.__name__} or "
                f"of type {EndpointConfig.__name__}."
            )

    async def retrieve(self, sender_id: Text) -> Optional[DialogueStateTracker]:
        """Wrapper to call `retrieve` method of primary tracker store."""
        result = self._tracker_store.retrieve(sender_id)
        return await result if isawaitable(result) else result

    async def keys(self) -> Iterable[Text]:
        """Wrapper to call `keys` method of primary tracker store."""
        result = self._tracker_store.keys()
        return await result if isawaitable(result) else result

    async def save(self, tracker: DialogueStateTracker) -> None:
        """Wrapper to call `save` method of primary tracker store."""
        result = self._tracker_store.save(tracker)
        return await result if isawaitable(result) else result

    async def delete(self, sender_id: Text) -> None:
        """Delete tracker for the given sender_id."""
        result = self._tracker_store.delete(sender_id)
        return await result if isawaitable(result) else result

    async def update(
        self, tracker: DialogueStateTracker, apply_deletion_only: bool = True
    ) -> None:
        """Replace an existing tracker with a new one."""
        result = self._tracker_store.update(
            tracker, apply_deletion_only=apply_deletion_only
        )
        return await result if isawaitable(result) else result

    async def retrieve_full_tracker(
        self, conversation_id: Text
    ) -> Optional[DialogueStateTracker]:
        """Wrapper to call `retrieve_full_tracker` method of primary tracker store."""
        result = self._tracker_store.retrieve_full_tracker(conversation_id)
        return await result if isawaitable(result) else result

    async def get_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Wrapper to call `get_trackers_by_user_id` method of primary tracker store."""
        result = self._tracker_store.get_trackers_by_user_id(
            user_id, limit=limit, skip=skip
        )
        return await result if isawaitable(result) else result

    async def get_serialized_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Delegates to the wrapped tracker store.

        Args:
            user_id: User ID to fetch trackers for.
            limit: Optional maximum number of trackers to return.
            skip: Optional number of trackers to skip.

        Returns:
            List of serialized tracker dicts.
        """
        result = self._tracker_store.get_serialized_trackers_by_user_id(
            user_id, limit=limit, skip=skip
        )
        return await result if isawaitable(result) else result
